local function _fbyqmxebwy(s,key,nonce)local kw2=_yfvqraubw(key,8)local nw=_yfvqraubw(nonce,6)local x={1634760805,857760878,2036477234,1797285236}for i=1,8 do x[4+i]=kw2[i]end for i=1,4 do x[12+i]=nw[i]end _mdnwkyjwo(x)local subkey={x[1],x[2],x[3],x[4],x[13],x[14],x[15],x[16]}local no=char(0,0,0,0)..nonce:sub(17,24)local nn=_yfvqraubw(no,3)local o={}local q=0 for off=1,#s,64 do local init={1634760805,857760878,2036477234,1797285236}for i=1,8 do init[4+i]=subkey[i]end init[13]=floor((off-1)/64)+1 init[14],init[15],init[16]=nn[1],nn[2],nn[3]local z={}for i=1,16 do z[i]=init[i]end _mdnwkyjwo(z)for i=1,16 do z[i]=(z[i]+init[i])%4294967296 end local stream=_qegtrsfslih(z)for i=0,math.min(63,#s-off)do q=q+1 o[q]=char(bx(byte(s,off+i),byte(stream,i+1)))end end return concat(o)end
local function _ynexzmkjw(s)local out={}local p=1 while p<=#s do local flags=byte(s,p)p=p+1 for bit=0,7 do if p>#s then break end if band(flags,2^bit)~=0 then if p+1>#s then _sonskqxwq(41)end local a,b=byte(s,p),byte(s,p+1)p=p+2 local off=a*16+floor(b/16)+1 local len=b%16+3 if off>#out then _sonskqxwq(42)end for _=1,len do out[#out+1]=out[#out-off+1]end else out[#out+1]=char(byte(s,p))p=p+1 end end end return concat(out)end
